* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: 'Barlow', sans-serif;
  min-height: 100vh;
  background:
    linear-gradient(160deg, rgba(0,0,0,0.82) 0%, rgba(12,0,0,0.72) 100%),
    url('https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1600&q=80') center/cover no-repeat fixed;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 16px;
}

/* ── CARD ── */
.card {
  width: 100%;
  max-width: 660px;
  background: var(--bg-card);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-card);
  backdrop-filter: blur(28px) saturate(1.4);
  -webkit-backdrop-filter: blur(28px) saturate(1.4);
  overflow: hidden;
  box-shadow:
    0 0 0 1px rgba(255,255,255,0.04) inset,
    0 40px 80px rgba(0,0,0,0.6),
    0 0 60px rgba(232,25,44,0.04);
  animation: cardIn .45s cubic-bezier(.22,.68,0,1.2);
}

@keyframes cardIn {
  from { opacity:0; transform:translateY(32px) scale(.98); }
  to   { opacity:1; transform:translateY(0) scale(1); }
}

/* ── LOGO ── */
.logo-bar {
  text-align: center;
  padding: 36px 0 22px;
  border-bottom: 1px solid var(--border);
  position: relative;
}
.logo-bar::after {
  content: '';
  position: absolute;
  bottom: -1px; left: 50%;
  transform: translateX(-50%);
  width: 60px; height: 2px;
  background: var(--red);
  border-radius: 99px;
}
.logo-bar .wordmark {
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 26px;
  font-weight: 800;
  letter-spacing: 5px;
  color: #fff;
}
.logo-bar .wordmark span { color: var(--red); }
.logo-bar .tagline-dashes {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 10px;
}
.logo-bar .tagline-dashes i {
  display: block;
  height: 2px;
  background: rgba(232,25,44,0.5);
  border-radius: 99px;
}
.logo-bar .tagline-dashes i:nth-child(1) { width: 40px; }
.logo-bar .tagline-dashes i:nth-child(2) { width: 20px; background: var(--red); }
.logo-bar .tagline-dashes i:nth-child(3) { width: 40px; }

/* ── STEP INDICATOR ── */
.steps-bar {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 22px 48px 18px;
  gap: 0;
  border-bottom: 1px solid var(--border);
}
.step-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  flex: 1;
  position: relative;
}
.step-item:not(:last-child)::after {
  content: '';
  position: absolute;
  top: 15px;
  left: 50%;
  width: 100%;
  height: 1px;
  background: rgba(255,255,255,0.08);
  z-index: 0;
  transition: background .4s;
}
.step-item.done:not(:last-child)::after { background: var(--red); }

.step-circle {
  width: 30px; height: 30px;
  border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,0.1);
  background: rgba(255,255,255,0.04);
  display: flex; align-items: center; justify-content: center;
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 12px; font-weight: 700;
  color: var(--text-muted);
  position: relative; z-index: 1;
  transition: all .35s cubic-bezier(.34,1.56,.64,1);
}
.step-item.active .step-circle {
  border-color: var(--red);
  background: var(--red);
  color: #fff;
  box-shadow: 0 0 0 5px var(--red-glow);
  transform: scale(1.1);
}
.step-item.done .step-circle {
  border-color: var(--red);
  background: var(--red);
  color: #fff;
  box-shadow: none;
  transform: scale(1);
}
.step-label {
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 1.5px;
  color: var(--text-muted);
  text-transform: uppercase;
  white-space: nowrap;
  transition: color .3s;
}

font-size: 10px;
  font-weight: 600;
  letter-spacing: 1.5px;
  color: var(--text-muted);
  text-transform: uppercase;
  white-space: nowrap;
  transition: color .3s;
}
.step-item.active .step-label { color: var(--red); }
.step-item.done .step-label { color: rgba(232,25,44,0.55); }

/* ── FORM BODY ── */
.form-body { padding: 32px 44px 40px; }

.step-heading { margin-bottom: 30px; }
.step-heading h2 {
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 34px;
  font-weight: 800;
  text-transform: uppercase;
  color: #fff;
  line-height: 1.05;
}
.step-heading h2 span { color: var(--red); display: block; }
.step-heading p {
  margin-top: 8px;
  font-size: 10.5px;
  letter-spacing: 2.5px;
  color: var(--text-muted);
  text-transform: uppercase;
