// ── VALIDATION ──
function validateStep(step) {
  let ok = true;

  function fail(inputId, errId) {
    const el = document.getElementById(inputId);
    const er = document.getElementById(errId);
    if (el) el.classList.add('invalid');
    if (er) er.classList.add('show');
    ok = false;
  }
  function clear(inputId, errId) {
    const el = document.getElementById(inputId);
    const er = document.getElementById(errId);
    if (el) el.classList.remove('invalid');
    if (er) er.classList.remove('show');
  }

if (step === 1) {
    const title = document.getElementById('title').value.trim();
    const type  = document.getElementById('type').value;
    const diff  = document.getElementById('difficulty').value;
    title ? clear('title','err-title') : fail('title','err-title');
    type  ? clear('type','err-type')   : fail('type','err-type');
    diff  ? clear('difficulty','err-difficulty') : fail('difficulty','err-difficulty');
  }

  if (step === 2) {
    startLocation ? clear('startSearch','err-start') : fail('startSearch','err-start');
    endLocation   ? clear('endSearch','err-end')     : fail('endSearch','err-end');
  }

if (step === 2) {
    startLocation ? clear('startSearch','err-start') : fail('startSearch','err-start');
    endLocation   ? clear('endSearch','err-end')     : fail('endSearch','err-end');
  }

  if (step === 3) {
    const sd = document.getElementById('startDate').value;
    const ed = document.getElementById('endDate').value;
    const t  = document.getElementById('time').value;
    const ms = document.getElementById('maxSeats').value;
    sd ? clear('startDate','err-startDate') : fail('startDate','err-startDate');
    ed ? clear('endDate','err-endDate')     : fail('endDate','err-endDate');
    t  ? clear('time','err-time')           : fail('time','err-time');
    ms ? clear('maxSeats','err-maxSeats')   : fail('maxSeats','err-maxSeats');
  }

if (step === 4) {
    const link = document.getElementById('communicationLink').value.trim();
    selectedCommType
      ? document.getElementById('err-commType').classList.remove('show')
      : (document.getElementById('err-commType').classList.add('show'), ok = false);
    link
      ? document.getElementById('err-commLink').classList.remove('show')
      : (document.getElementById('err-commLink').classList.add('show'), ok = false);
  }

  return ok;
}

