  });
}

// ── AUTOCOMPLETE ──
let debounceTimer;
function setupAutocomplete(inputId, dropdownId, mapRef, markerRef, locSetter, addrSetter, mapWrapId) {
  const input    = document.getElementById(inputId);
  const dropdown = document.getElementById(dropdownId);
  const mapWrap  = document.getElementById(mapWrapId);

input.addEventListener('input', () => {
    clearTimeout(debounceTimer);
    const q = input.value.trim();
    if (q.length < 3) { dropdown.classList.remove('open'); return; }
    debounceTimer = setTimeout(() => fetchSuggestions(q, dropdown, mapRef, markerRef, locSetter, addrSetter, mapWrap), 300);
  });

  document.addEventListener('click', e => {
    if (!input.contains(e.target) && !dropdown.contains(e.target)) {
      dropdown.classList.remove('open');
    }
  });
}

async function fetchSuggestions(q, dropdown, mapRef, markerRef, locSetter, addrSetter, mapWrap) {
  try {
    const res  = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(q)}&limit=5`);
    const data = await res.json();
    renderDropdown(data, dropdown, mapRef, markerRef, locSetter, addrSetter, mapWrap);
  } catch(e) { console.error(e); }
}

function renderDropdown(data, dropdown, mapRef, markerRef, locSetter, addrSetter, mapWrap) {
  dropdown.innerHTML = '';
  if (!data.length) { dropdown.classList.remove('open'); return; }

  const header = document.createElement('div');
  header.className = 'ac-header';
  header.innerHTML = `<span class="loc-title">Locations</span><span class="osm-tag">Via OpenStreetMap</span>`;
  dropdown.appendChild(header);

  data.forEach(place => {
    const parts = place.display_name.split(',');
    const name  = parts[0].trim();
    const sub   = parts.slice(1, 3).join(',').trim().toUpperCase();
    const lat   = parseFloat(place.lat).toFixed(4);
    const lon   = parseFloat(place.lon).toFixed(4);

item.onclick = () => {
