      setTimeout(() => mapRef().invalidateSize(), 100);
      if (markerRef.current) mapRef().removeLayer(markerRef.current);
      markerRef.current = L.marker([lLat, lLon]).addTo(mapRef());
      locSetter({ lat: lLat, lng: lLon });
      addrSetter(place.display_name);
      dropdown.classList.remove('open');

      // update input display
      dropdown.previousElementSibling
        ? (dropdown.parentElement.querySelector('input').value = name + ', ' + sub)
        : null;
      const inp = dropdown.parentElement.querySelector('input');
      if (inp) inp.value = name + (sub ? ', ' + sub : '');
    };

    dropdown.appendChild(item);
  });

  dropdown.classList.add('open');
}

