async function submitRide() {
  if (!validateStep(4)) return;

  const btn = document.getElementById('submitBtn');
  btn.textContent = 'LAUNCHING...';
  btn.disabled = true;

  try {
    const fd = new FormData();
    const bannerFile = document.getElementById('bannerInput').files[0];
    if (bannerFile) fd.append('banner', bannerFile);

fd.append('title',             document.getElementById('title').value.trim());
    fd.append('type',              document.getElementById('type').value);
    fd.append('difficulty',        document.getElementById('difficulty').value);
    fd.append('startDate',         document.getElementById('startDate').value);
    fd.append('endDate',           document.getElementById('endDate').value);
    fd.append('time',              document.getElementById('time').value);
    fd.append('length',            document.getElementById('length').value);
    fd.append('maxSeats',          document.getElementById('maxSeats').value);
    fd.append('entryFee',          document.getElementById('entryFee').value || 0);
    fd.append('communicationType', selectedCommType);
    fd.append('communicationLink', document.getElementById('communicationLink').value.trim());
    fd.append('startAddress',      startAddress);
    fd.append('endAddress',        endAddress);

fd.append('communicationLink', document.getElementById('communicationLink').value.trim());
    fd.append('startAddress',      startAddress);
    fd.append('endAddress',        endAddress);
    fd.append('startLocation', JSON.stringify({
      type: 'Point',
      coordinates: [startLocation.lng, startLocation.lat]
    }));
    fd.append('endLocation', JSON.stringify({
      type: 'Point',
      coordinates: [endLocation.lng, endLocation.lat]
    }));

    console.log(fd);

const res = await fetch('http://localhost:3000/rides/create_ride', {
      method: 'POST',
      credentials: 'include',
      body: fd
    });

    if (!res.ok) {
      const err = await res.json();
      throw new Error(err.message || 'Server error');
    }

    const result = await res.json();
    if (result.success) {
      document.getElementById('stepsBar').style.display = 'none';
      document.getElementById('step4').style.display = 'none';
      document.getElementById('successState').style.display = 'block';
    } else {
      throw new Error(result.message || 'Unknown error');
    }

  } catch (err) {
    alert('Error: ' + err.message);
    btn.textContent = '🏍 LAUNCH RIDE →';
    btn.disabled = false;
  }
}
