/* ══════════════════════════════════════
   NAVBAR — matches dashboard but landing-specific
══════════════════════════════════════ */
nav {
  position: fixed; top:0; left:0; right:0; z-index:200;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  height: 70px;
  padding: 0 2rem;
  background: rgba(13,13,13,0.0);
  border-bottom: 2px solid transparent;
  transition: background .35s var(--ease), border-color .35s var(--ease), height .35s var(--ease);
}
nav.scrolled {
  background: rgba(13,13,13,0.96);
  backdrop-filter: blur(14px);
  border-bottom: 2px solid var(--red);
  height: 62px;
}

.nav-left, .nav-right { display:flex; align-items:center; gap:1.6rem; }
.nav-right { justify-content:flex-end; }
.nav-center { display:flex; align-items:center; justify-content:center; }

.nav-left, .nav-right { display:flex; align-items:center; gap:1.6rem; }
.nav-right { justify-content:flex-end; }
.nav-center { display:flex; align-items:center; justify-content:center; }

.nav-link {
  font-family:'Barlow',sans-serif;
  font-size:.82rem; font-weight:500;
  letter-spacing:.12em; text-transform:uppercase;
  color: var(--text-dim);
  position: relative;
  padding: .25rem 0;
  transition: color .2s;
}
.nav-link::after {
  content:''; position:absolute; bottom:-3px; left:0;
  width:0; height:2px; background: var(--red);
  transition: width .25s var(--ease);
}
.nav-link:hover { color: var(--text); }
.nav-link:hover::after { width:100%; }

.nav-logo-text {
  font-family:'Montserrat',sans-serif;
  font-size:1.5rem; font-weight:900;
  letter-spacing:.18em;
  color: var(--text);
}
.nav-logo-text span { color: var(--red); }
.nav-logo-img { height:32px; width:auto; }

.nav-signin {
  font-family:'Montserrat',sans-serif;
  font-size:.7rem; font-weight:700;
  letter-spacing:.14em; text-transform:uppercase;
  color: var(--text-dim);
  transition: color .2s;
}
.nav-signin:hover { color: var(--text); }

.btn-primary, .btn-outline, .btn-ghost {
  font-family:'Montserrat',sans-serif;
  font-weight: 800;
  letter-spacing: .16em;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: inline-flex; align-items: center; gap: .5rem;
  position: relative; overflow: hidden;
  transition: box-shadow .25s var(--ease), color .25s var(--ease), background .25s var(--ease), transform .15s var(--ease);
  text-decoration: none;
  border: 2px solid var(--red);
  white-space: nowrap;
}

.btn-primary {
  font-size: .72rem;
  padding: .7rem 1.5rem;
  background: var(--red); color: #fff;
}
.btn-primary:hover {
  box-shadow: 0 0 30px var(--red-glow);
  transform: translateY(-2px);
}
.btn-primary.lg { font-size:.84rem; padding: 1rem 2.4rem; }

.btn-outline {
  font-size: .72rem;
  padding: .7rem 1.5rem;
  background: transparent; color: var(--text);
}
.btn-outline:hover {
  background: var(--red); color:#fff;
  box-shadow: 0 0 30px var(--red-glow);
  transform: translateY(-2px);
}
.btn-outline.lg { font-size:.84rem; padding: 1rem 2.4rem; }

.btn-ghost {
  font-size: .72rem;
  padding: .7rem 1.5rem;
  background: transparent; color: var(--text-dim);
  border: 1.5px solid var(--border);
}
.btn-ghost:hover {
  border-color: var(--red); color: var(--red);
}

/* ══════════════════════════════════════
   HERO
══════════════════════════════════════ */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex; align-items: center;
  overflow: hidden;
  isolation: isolate;
}

.hero-bg {
  position: absolute; inset:0;
  background:
    linear-gradient(135deg, rgba(0,0,0,0.6) 0%, rgba(13,13,13,0.85) 60%, rgba(13,13,13,0.95) 100%),
    url('https://images.unsplash.com/photo-1558981403-c5f9899a28bc?w=1920&q=85') center/cover no-repeat;
  z-index:-2;
  transform: translateZ(0);
  will-change: transform;
}

/* red diagonal slash accent on hero */
.hero-accent {
  position: absolute; right:-10%; top:0; bottom:0; width:60%;
  background: linear-gradient(115deg, transparent 40%, rgba(232,0,13,0.18) 50%, transparent 60%);
  z-index:-1; pointer-events:none;
}

.hero-content {
  max-width: 1280px;
  width: 100%;
  margin: 0 auto;
  padding: 0 2.4rem;
  position: relative;
}

.hero-content {
  max-width: 1280px;
  width: 100%;
  margin: 0 auto;
  padding: 0 2.4rem;
  position: relative;
}

.hero-eyebrow {
  display: inline-flex; align-items: center; gap: .8rem;
  font-family:'Oswald',sans-serif;
  font-size:.78rem; font-weight:500;
  letter-spacing:.32em; text-transform:uppercase;
  color: var(--red);
  margin-bottom: 1.4rem;
  opacity: 0;
  animation: hero-fade .8s var(--ease-out) .2s forwards;
}
.hero-eyebrow::before {
  content:''; width:32px; height:2px; background: var(--red);
}

.hero-title {
  font-family:'Montserrat',sans-serif;
  font-size: clamp(3rem, 8vw, 6.4rem);
  font-weight: 900;
  line-height: .95;
  letter-spacing: -.03em;
  text-transform: uppercase;
  margin-bottom: 1.6rem;
  color: var(--text);
  max-width: 14ch;
}
.hero-title-line {
  display: block;
  opacity: 0;
  transform: translateY(40px);
  animation: hero-rise 1s var(--ease-out) forwards;
}
.hero-title-line:nth-child(1) { animation-delay: .35s; }
.hero-title-line:nth-child(2) { animation-delay: .5s; color: var(--red); font-style: italic; }
.hero-title-line:nth-child(3) { animation-delay: .65s; }

.hero-sub {
  font-family:'Barlow',sans-serif;
  font-size: clamp(1rem, 1.6vw, 1.2rem);
  font-weight: 400;
  color: var(--text-dim);
  max-width: 540px;
  line-height: 1.6;
  margin-bottom: 2.4rem;
  opacity: 0;
  animation: hero-fade 1s var(--ease-out) .9s forwards;
}

.hero-ctas {
  display: flex; gap: 1rem; flex-wrap: wrap;
  margin-bottom: 3.6rem;
  opacity: 0;
  animation: hero-fade 1s var(--ease-out) 1.1s forwards;
}

.hero-live {
  display: inline-flex; align-items: center; gap: .7rem;
  font-family:'Oswald',sans-serif;
  font-size:.85rem; font-weight:500;
  letter-spacing:.18em; text-transform:uppercase;
  color: var(--text-dim);
  opacity: 0;
  animation: hero-fade 1s var(--ease-out) 1.3s forwards;
}
.hero-live-dot {
  width:8px; height:8px; border-radius:50%;
  background: var(--red);
  animation: pulse 1.6s ease-in-out infinite;
  box-shadow: 0 0 0 0 rgba(232,0,13,.6);
}
.hero-live strong { color: var(--text); font-weight:700; margin: 0 .2rem; }

@keyframes pulse {
  0%   { box-shadow: 0 0 0 0 rgba(232,0,13,.6); }
  70%  { box-shadow: 0 0 0 14px rgba(232,0,13,0); }
  100% { box-shadow: 0 0 0 0 rgba(232,0,13,0); }
}
@keyframes hero-fade { from { opacity:0; } to { opacity:1; } }
@keyframes hero-rise { from { opacity:0; transform: translateY(40px); } to { opacity:1; transform: translateY(0); } }

.scroll-cue {
  position: absolute; bottom: 2.4rem; left: 50%;
  transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: .6rem;
  opacity: 0;
  animation: hero-fade 1.2s var(--ease-out) 1.6s forwards;
}
.scroll-cue-line {
  width:1px; height:40px;
  background: linear-gradient(to bottom, transparent, var(--red));
  animation: scroll-cue-move 1.8s var(--ease) infinite;
}
.scroll-cue-text {
  font-family:'Oswald',sans-serif;
  font-size:.6rem; letter-spacing:.32em;
  color: var(--text-muted);
  text-transform: uppercase;
  writing-mode: vertical-rl;
}
@keyframes scroll-cue-move {
  0%   { transform: translateY(-12px); opacity: 0; }
  50%  { opacity: 1; }
  100% { transform: translateY(12px);  opacity: 0; }
}

/* ══════════════════════════════════════
   SECTION SHELL
══════════════════════════════════════ */
section {
  padding: 7rem 2.4rem;
  max-width: 1280px;
  margin: 0 auto;
  position: relative;
}
@media (max-width: 760px) { section { padding: 5rem 1.4rem; } }

.section-eyebrow {
  display: inline-flex; align-items: center; gap: .7rem;
  font-family:'Oswald',sans-serif;
  font-size:.72rem; font-weight:500;
  letter-spacing:.32em; text-transform:uppercase;
  color: var(--red);
  margin-bottom: 1rem;
}
.section-eyebrow::before {
  content:''; width:24px; height:2px; background: var(--red);
}

.section-title {
  font-family:'Montserrat',sans-serif;
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -.02em;
  text-transform: uppercase;
  margin-bottom: 1rem;
  color: var(--text);
  max-width: 18ch;
}
.section-title em {
  font-style: italic;
  color: var(--red);
}

.section-lead {
  font-family:'Barlow',sans-serif;
  font-size: 1.05rem;
  color: var(--text-dim);
  max-width: 580px;
  line-height: 1.7;
  margin-bottom: 3rem;
}

/* reveal-on-scroll */
.reveal {
  opacity: 0;
  transform: translateY(40px);
  transition: opacity .9s var(--ease-out), transform .9s var(--ease-out);
}
.reveal.is-visible {
  opacity: 1; transform: translateY(0);
}
.reveal.delay-1 { transition-delay: .08s; }
.reveal.delay-2 { transition-delay: .16s; }
.reveal.delay-3 { transition-delay: .24s; }
.reveal.delay-4 { transition-delay: .32s; }

/* ══════════════════════════════════════
   STATS BAR
══════════════════════════════════════ */
.stats-bar {
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  background: var(--bg-alt);
  padding: 0;
  margin: 0;
  max-width: none;
}
.stats-bar-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 2.4rem 2.4rem;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}
@media (max-width: 760px) { .stats-bar-inner { grid-template-columns: repeat(2, 1fr); } }

.stat {
  text-align: center;
  border-right: 1px solid var(--border);
}
.stat:last-child { border-right: none; }
@media (max-width: 760px) {
  .stat:nth-child(2) { border-right: none; }
}
.stat-number {
  font-family:'Montserrat',sans-serif;
  font-size: clamp(2rem, 4vw, 3.4rem);
  font-weight: 900;
  font-style: italic;
  color: var(--red);
  line-height: 1;
  letter-spacing: -.02em;
}
.stat-label {
  font-family:'Oswald',sans-serif;
  font-size: .7rem; font-weight: 400;
  letter-spacing: .26em; text-transform: uppercase;
  color: var(--text-dim);
  margin-top: .6rem;
}

/* ══════════════════════════════════════
   VALUE PROPS GRID
══════════════════════════════════════ */
.value-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.4rem;
  margin-top: 2rem;
}
@media (max-width: 1000px) { .value-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 540px)  { .value-grid { grid-template-columns: 1fr; } }

.value-card {
  background: var(--card-bg);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  padding: 1.8rem 1.6rem 1.6rem;
  transition: border-color .3s var(--ease), transform .3s var(--ease), background .3s var(--ease);
  position: relative; overflow: hidden;
}
.value-card:hover {
  border-color: var(--red);
  transform: translateY(-6px);
  background: var(--card-bg-hi);
}
.value-card::after {
  content:''; position: absolute; top:0; left:0;
  width: 0; height: 3px; background: var(--red);
  transition: width .35s var(--ease);
}
.value-card:hover::after { width: 100%; }

.value-icon {
  width: 48px; height: 48px;
  border-radius: 8px;
  background: var(--red-glow);
  border: 1px solid var(--red);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.4rem;
  margin-bottom: 1.2rem;
  transition: background .3s var(--ease), transform .35s var(--ease-back);
}
.value-card:hover .value-icon {
  background: var(--red);
  transform: rotate(-8deg) scale(1.05);
}
.value-title {
  font-family:'Montserrat',sans-serif;
  font-size: 1rem; font-weight: 800;
  letter-spacing: -.01em;
  margin-bottom: .5rem;
  color: var(--text);
}
.value-desc {
  font-family:'Barlow',sans-serif;
  font-size: .9rem;
  color: var(--text-dim);
  line-height: 1.55;
}

/* ══════════════════════════════════════
   AUDIENCE SPLITS
══════════════════════════════════════ */
.audience {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  margin-bottom: 6rem;
}
.audience.reverse { direction: rtl; }
.audience.reverse > * { direction: ltr; }
@media (max-width: 880px) {
  .audience { grid-template-columns: 1fr; gap: 2rem; }
  .audience.reverse { direction: ltr; }
}

.audience-image {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  aspect-ratio: 4/5;
  background: linear-gradient(145deg, #1c1c1c, #0d0d0d);
  border: 1.5px solid var(--border);
  transition: transform .6s var(--ease), border-color .6s var(--ease);
}
.audience-image::after {
  content:''; position: absolute; inset:0;
  background: linear-gradient(to top, rgba(0,0,0,.6) 0%, transparent 50%);
  pointer-events: none;
}
.audience-image img {
  width:100%; height:100%; object-fit: cover;
  transition: transform .8s var(--ease), filter .6s var(--ease);
  filter: grayscale(40%) brightness(.8);
}
.audience-image:hover img {
  transform: scale(1.05);
  filter: grayscale(0%) brightness(1);
}
.audience-image-tag {
  position: absolute; top: 18px; left: 18px;
  font-family:'Montserrat',sans-serif;
  font-size:.62rem; font-weight: 800;
  letter-spacing:.18em; text-transform: uppercase;
  background: var(--red);
  color: #fff;
  padding: .35rem .8rem;

font-family:'Montserrat',sans-serif;
  font-size:.62rem; font-weight: 800;
  letter-spacing:.18em; text-transform: uppercase;
  background: var(--red);
  color: #fff;
  padding: .35rem .8rem;
  border-radius: 4px;
  z-index: 2;
}

.audience-content { padding: 1rem 0; }
.audience-eyebrow {
  font-family:'Oswald',sans-serif;
  font-size:.72rem; font-weight:500;
  letter-spacing:.32em; text-transform:uppercase;
  color: var(--red);
  margin-bottom: .8rem;
}
.audience-title {
  font-family:'Montserrat',sans-serif;
  font-size: clamp(1.8rem, 3vw, 2.6rem);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -.02em;
  text-transform: uppercase;
  margin-bottom: 1.2rem;
  color: var(--text);
}
.audience-title em { font-style: italic; color: var(--red); }
.audience-desc {
  font-family:'Barlow',sans-serif;
  font-size: 1rem;
  color: var(--text-dim);
  line-height: 1.7;
  margin-bottom: 1.6rem;
}
.audience-bullets {
  list-style: none;
  margin-bottom: 2rem;
}
.audience-bullets li {
  display: flex; align-items: flex-start; gap: .8rem;
  padding: .65rem 0;
  border-bottom: 1px solid var(--border);
  font-family:'Barlow',sans-serif;
  font-size: .95rem;
  color: var(--text);
}
.audience-bullets li::before {

padding: .65rem 0;
  border-bottom: 1px solid var(--border);
  font-family:'Barlow',sans-serif;
  font-size: .95rem;
  color: var(--text);
}
.audience-bullets li::before {
  content: '→';
  color: var(--red);
  font-family:'Oswald',sans-serif;
  font-weight: 700;
  flex-shrink: 0;
}

/* ══════════════════════════════════════
   HOW IT WORKS
══════════════════════════════════════ */
.steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  margin-top: 2rem;
  position: relative;
}
.steps::before {
  content:'';
  position: absolute; top: 32px; left: 6%; right: 6%;
  height: 2px;
  background: linear-gradient(to right, var(--border) 0%, var(--red) 50%, var(--border) 100%);
  z-index: 0;
}
@media (max-width: 880px) {
  .steps { grid-template-columns: 1fr; gap: 2.4rem; }
  .steps::before { display: none; }
}

.step {
  text-align: center;
  position: relative;
  z-index: 1;
  padding: 0 1rem;
}
.step-number {
  width: 64px; height: 64px;
  border-radius: 50%;
  background: var(--bg);
  border: 2px solid var(--red);
  margin: 0 auto 1.4rem;
  display: flex; align-items: center; justify-content: center;
  font-family:'Montserrat',sans-serif;
  font-size: 1.6rem; font-weight: 900;
  font-style: italic;
  color: var(--red);
  position: relative;
  transition: background .3s var(--ease), color .3s var(--ease), transform .3s var(--ease);
}
.step:hover .step-number {
  background: var(--red); color: #fff;
  transform: scale(1.08);
}
.step-title {
  font-family:'Montserrat',sans-serif;
  font-size: 1.2rem; font-weight: 800;
  letter-spacing: -.01em;
  margin-bottom: .6rem;
  color: var(--text);
  text-transform: uppercase;
}
.step-desc {
  font-family:'Barlow',sans-serif;
  font-size: .95rem;
  color: var(--text-dim);
  line-height: 1.6;
  max-width: 280px;
  margin: 0 auto;
}

/* ══════════════════════════════════════
   FEATURED RIDES
══════════════════════════════════════ */
.rides-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.4rem;
  margin-top: 2rem;
}

.feat-ride-card {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  aspect-ratio: 3/4;
  background: var(--card-bg);
  border: 1.5px solid var(--border);
  transition: transform .35s var(--ease), border-color .35s var(--ease), box-shadow .35s var(--ease);
  cursor: pointer;
  display: block;
}
.feat-ride-card:hover {
  transform: translateY(-6px) scale(1.01);
  border-color: var(--red);
  box-shadow: 0 16px 40px rgba(0,0,0,.6), 0 0 0 1px var(--red-glow);
}
.feat-ride-bg {
  position: absolute; inset:0;
  background-size: cover; background-position: center;
  transition: filter .4s var(--ease), transform .4s var(--ease);
}
.feat-ride-card:hover .feat-ride-bg {
  filter: brightness(.4) saturate(.7);
  transform: scale(1.06);
}
.feat-ride-vignette {
  position: absolute; inset:0;
  background: linear-gradient(to top, rgba(0,0,0,.92) 0%, rgba(0,0,0,.1) 55%, transparent 100%);
}
.feat-ride-chip {
  position: absolute; top: 12px; left: 12px;

position: absolute; inset:0;
  background: linear-gradient(to top, rgba(0,0,0,.92) 0%, rgba(0,0,0,.1) 55%, transparent 100%);
}
.feat-ride-chip {
  position: absolute; top: 12px; left: 12px;
  font-family:'Montserrat',sans-serif;
  font-size:.55rem; font-weight: 800;
  letter-spacing:.18em; text-transform: uppercase;
  background: var(--red); color: #fff;
  padding: .22rem .65rem; border-radius: 4px;
  z-index: 2;
  transition: opacity .3s;
}
.feat-ride-card:hover .feat-ride-chip { opacity: 0; }
.feat-ride-bottom {
  position: absolute; bottom:0; left:0; right:0;
  padding: 1rem 1.1rem;
  z-index: 2;
}
.feat-ride-title {
  font-family:'Montserrat',sans-serif;
  font-size: 1rem; font-weight: 800;
  line-height: 1.2;
  color: #fff;
  text-shadow: 0 2px 8px rgba(0,0,0,.8);
}
.feat-ride-meta {
  font-family:'Oswald',sans-serif;
  font-size:.7rem; font-weight: 400;
  letter-spacing:.16em; text-transform: uppercase;
  color: rgba(255,255,255,.7);
  margin-top: .35rem;
}
.feat-ride-hover {

font-family:'Oswald',sans-serif;
  font-size:.7rem; font-weight: 400;
  letter-spacing:.16em; text-transform: uppercase;
  color: rgba(255,255,255,.7);
  margin-top: .35rem;
}
.feat-ride-hover {
  position: absolute; inset: 0;
  padding: 1.3rem;
  z-index: 3;
  display: flex; flex-direction: column; justify-content: center;
  opacity: 0;
  transition: opacity .3s var(--ease);
}
.feat-ride-card:hover .feat-ride-hover { opacity: 1; }
.feat-ride-card:hover .feat-ride-bottom { opacity: 0; }
.fh-title {
  font-family:'Montserrat',sans-serif;
  font-size: 1.15rem; font-weight: 800;
  color: #fff; line-height: 1.2;
  margin-bottom: .8rem;
}
.fh-route {
  font-family:'Barlow',sans-serif;
  font-size:.85rem; color: rgba(255,255,255,.85);
  margin-bottom: .8rem; line-height: 1.5;
}
