document.querySelectorAll('.reveal').forEach(el => revealObserver.observe(el));

  /* ══ ANIMATED COUNTERS ══ */
  function animateCount(el) {
    const target = parseInt(el.dataset.count, 10);
    if (!Number.isFinite(target)) return;
    const duration = 1600;
    const start = performance.now();
    function step(now) {
      const t = Math.min((now - start) / duration, 1);
      // ease-out cubic
      const eased = 1 - Math.pow(1 - t, 3);
      el.textContent = Math.floor(target * eased).toLocaleString();
      if (t < 1) requestAnimationFrame(step);
      else el.textContent = target.toLocaleString() + (target >= 100 ? '+' : '');
    }
    requestAnimationFrame(step);
  }

  const countObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        animateCount(entry.target);
        countObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.5 });

document.querySelectorAll('[data-count]').forEach(el => countObserver.observe(el));

  /* ══ FAQ ACCORDION ══ */
  document.querySelectorAll('.faq-q').forEach(btn => {
    btn.addEventListener('click', () => {
      const item = btn.parentElement;
      const wasOpen = item.classList.contains('open');
      // close all
      document.querySelectorAll('.faq-item.open').forEach(i => i.classList.remove('open'));
      if (!wasOpen) item.classList.add('open');
    });
  });

  /* ══ HERO PARALLAX (subtle) ══ */
  const heroBg = document.querySelector('.hero-bg');
  if (heroBg && window.matchMedia('(min-width: 880px)').matches) {
    window.addEventListener('scroll', () => {
      const y = window.scrollY;
      if (y < 700) {
        heroBg.style.transform = `translate3d(0, ${y * 0.3}px, 0) scale(${1 + y * 0.0003})`;
      }
    }, { passive: true });
  }

/* ══ SMOOTH SCROLL FOR ANCHOR LINKS ══ */
  document.querySelectorAll('a[href^="#"]').forEach(a => {
    a.addEventListener('click', (e) => {
      const target = document.querySelector(a.getAttribute('href'));
      if (target) {
        e.preventDefault();
        const offset = 80;
        const top = target.getBoundingClientRect().top + window.scrollY - offset;
        window.scrollTo({ top, behavior: 'smooth' });
      }
    });
  });

  /* ══ LIVE COUNT (small flair) ══ */
  // randomize between 9-18 for a "live" feel
  const liveEl = document.getElementById('liveCount');
  if (liveEl) {
    const n = 9 + Math.floor(Math.random() * 10);
    liveEl.textContent = n;
  }
})();
