  <!-- NAVBAR -->
  <nav>
    <!-- LEFT: search -->
    <div class="nav-left">
      <input class="nav-search" type="text" placeholder="Search for Rides..." />
    </div>

function difficultyClass(d = '') {
      const map = { easy: 'difficulty-easy', moderate: 'difficulty-moderate', hard: 'difficulty-hard', extreme: 'difficulty-extreme' };
      return map[d.toLowerCase()] || 'difficulty-moderate';
    }

    function renderRides(rides) {
      const grid = document.getElementById('rides-grid');
      grid.innerHTML = '';

      if (!rides || rides.length === 0) {
        grid.innerHTML = `
          <div class="state-container">
            <span class="error-icon">🏍️</span>
            <span class="state-label">No rides yet — create your first one!</span>
          </div>`;
        return;
      }

      rides.forEach((ride, i) => {
        const card = document.createElement('a');
        card.className = 'ride-card';
        card.href = `ride_details.html?id=${ride._id}`;
        card.style.animationDelay = `${i * 80}ms`;

const fallback = 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=600&q=70';
        const imgSrc = ride.banner || fallback;

        card.innerHTML = `
          <img class="ride-card-img" src="${imgSrc}" alt="${ride.title}"
               onerror="this.src='${fallback}'"/>
          <div class="ride-card-default">
            <span class="ride-card-title-default">${ride.title || 'Untitled Ride'}</span>
          </div>
          <div class="ride-card-hover">
            <span class="ride-card-title-hover">${ride.title || 'Untitled Ride'}</span>
            <span class="ride-card-type">${ride.type || 'Ride'}</span>
            <span class="ride-card-difficulty ${difficultyClass(ride.difficulty)}">${ride.difficulty || 'Moderate'}</span>
          </div>
        `;

        grid.appendChild(card);
      });
    }

grid.appendChild(card);
      });
    }

    async function fetchRides() {
      try {
        const res = await fetch('https://ride-sync-backend-v1.onrender.com/rides/org_rides', {
          method: 'GET',
          headers: {
            'Content-Type': 'application/json'
          },
          credentials: 'include'
        });

        if (!res.ok) throw new Error(`HTTP ${res.status}`);

        const json = await res.json();

        if (json.success && Array.isArray(json.data)) {
          renderRides(json.data);
        } else {
          throw new Error('Unexpected response shape');
        }

      } catch (err) {
        console.error('Failed to fetch rides:', err);
        document.getElementById('rides-grid').innerHTML = `
          <div class="state-container">
            <span class="error-icon">⚠️</span>
            <span class="state-label">Failed to load rides</span>
          </div>`;
      }
    }

    fetchRides();
  </script>
