function goTo2() {
  const uEl  = document.getElementById('f1-username');
  const eEl  = document.getElementById('f1-email');
  const u    = uEl.value.trim();
  const e    = eEl.value.trim();
  const p    = document.getElementById('f1-password').value;
  const err  = document.getElementById('p1-err');

  // username: no spaces
  if (!u || /\s/.test(u)) {
    err.textContent = 'Username cannot contain spaces.';
    err.classList.add('show');
    uEl.classList.add('input-error');
    return;
  }
  uEl.classList.remove('input-error');

  // email: valid format
  const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);
  if (!emailOk) {
    err.textContent = 'Please enter a valid email address.';
    err.classList.add('show');
    eEl.classList.add('input-error');
    return;
  }
  eEl.classList.remove('input-error');

// password
  const pwOk = validatePassword(p);
  if (!pwOk) {
    err.textContent = 'Password does not meet all requirements.';
    err.classList.add('show');
    return;
  }

  err.classList.remove('show');
  state.username = u; state.email = e; state.password = p;
  showPage('p1','p2');
}

function goTo3() {
  const err = document.getElementById('p2-err');
  if (!state.role) { err.style.display='block'; return; }
  err.style.display='none';
  document.querySelectorAll('.role-panel').forEach(p => p.classList.remove('active'));
  document.getElementById('panel-' + state.role).classList.add('active');
  const titles = {
    rider:'Your Ride<br/><span>Profile</span>',
    organizer:'Your Club<br/><span>Profile</span>',
    sponsor:'Your Brand<br/><span>Profile</span>'
  };
  document.getElementById('p3-title').innerHTML = titles[state.role];
  showPage('p2','p3');
}

