/* ── PASSWORD VALIDATION ───────────────────── */
function validatePassword(p) {
  return p.length >= 8 && p.length <= 32
      && /[A-Z]/.test(p)
      && /[^a-zA-Z0-9]/.test(p)
      && /^[a-zA-Z0-9!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?`~]+$/.test(p);
}

document.getElementById('f1-password').addEventListener('input', function(){
  const p = this.value;
  toggle('ph-len',     p.length >= 8 && p.length <= 32);
  toggle('ph-upper',   /[A-Z]/.test(p));
  toggle('ph-special', /[^a-zA-Z0-9]/.test(p));
  toggle('ph-alnum',   /[a-zA-Z0-9]/.test(p));
});
function toggle(id, ok) {
  document.getElementById(id).classList.toggle('ok', ok);
}

/* ── USERNAME — live validation ────────────── */
document.getElementById('f1-username').addEventListener('input', function(){
  const hint = document.getElementById('username-hint');
  const val  = this.value;
  if (!val) {
    hint.textContent = 'No spaces — use underscores or hyphens instead';
    hint.className   = 'field-hint';
    this.classList.remove('input-error','input-ok');
    return;
  }
  if (/\s/.test(val)) {
    hint.textContent = '✕ Spaces are not allowed';
    hint.className   = 'field-hint hint-error';
    this.classList.add('input-error');
    this.classList.remove('input-ok');
  } else {
    hint.textContent = '✓ Looks good';
    hint.className   = 'field-hint hint-ok';
    this.classList.remove('input-error');
    this.classList.add('input-ok');
  }
});

/* ── EMAIL — live validation ───────────────── */
document.getElementById('f1-email').addEventListener('input', function(){
  const hint = document.getElementById('email-hint');
  const val  = this.value.trim();
  if (!val) {
    hint.textContent = '';
    hint.className   = 'field-hint';
    this.classList.remove('input-error','input-ok');
    return;
  }
  const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val);
  if (ok) {
    hint.textContent = '✓ Valid email';
    hint.className   = 'field-hint hint-ok';
    this.classList.remove('input-error');
    this.classList.add('input-ok');
  } else {
    hint.textContent = '✕ Enter a valid email (e.g. you@domain.com)';
    hint.className   = 'field-hint hint-error';
    this.classList.add('input-error');
    this.classList.remove('input-ok');
  }
});

