document.getElementById('f1-pfp').addEventListener('change', function(){
  const file = this.files[0];
  if (!file) return;
  if (file.size > 2 * 1024 * 1024) {
    document.getElementById('pfp-err').classList.add('show'); return;
  }
  document.getElementById('pfp-err').classList.remove('show');
  state.pfp = file;
  const r = new FileReader();
