/* ── MULTI-SELECT ──────────────────────────── */
const msState = { bike: [], style: [] };

function toggleMs(key) {
  const dd   = document.getElementById(key+'-dropdown');
  const disp = document.getElementById(key+'-display');
  dd.classList.toggle('open');
  disp.classList.toggle('open');
}

function pickMs(key, val) {
  const arr = msState[key];
  const idx = arr.indexOf(val);
  if (idx > -1) arr.splice(idx, 1);
  else arr.push(val);
  renderTags(key);
  document.querySelectorAll(`#${key}-dropdown .ms-option`).forEach(o => {
    o.classList.toggle('chosen', arr.includes(o.textContent.trim()));
  });
}

function renderTags(key) {
  const disp = document.getElementById(key+'-display');
  const ph   = document.getElementById(key+'-ph');
  const arr  = msState[key];
  disp.querySelectorAll('.ms-tag').forEach(t => t.remove());
  if (arr.length === 0) { ph.style.display = 'inline'; return; }
  ph.style.display = 'none';
  arr.forEach(v => {
    const tag = document.createElement('div');
    tag.className = 'ms-tag';
    tag.innerHTML = `${v}<span class="ms-tag-remove" onclick="removeTag('${key}','${v}',event)">×</span>`;
    disp.appendChild(tag);
  });
}

function removeTag(key, val, e) {
  e.stopPropagation();
  const idx = msState[key].indexOf(val);
  if (idx > -1) msState[key].splice(idx, 1);
  renderTags(key);
  document.querySelectorAll(`#${key}-dropdown .ms-option`).forEach(o => {
    o.classList.toggle('chosen', msState[key].includes(o.textContent.trim()));
  });
}

document.addEventListener('click', e => {
  ['bike','style'].forEach(key => {
    const disp = document.getElementById(key+'-display');
    const dd   = document.getElementById(key+'-dropdown');
    if (disp && !disp.contains(e.target) && dd && !dd.contains(e.target)) {
      dd.classList.remove('open'); disp.classList.remove('open');
    }
  });
  // close city suggestions on outside click
  const cityWrap = document.querySelector('.city-search-wrap');
  const sugg     = document.getElementById('city-suggestions');
  if (cityWrap && sugg && !cityWrap.contains(e.target)) {
    sugg.classList.remove('open');
  }
});

