async function fetchCities(query) {
  const spinner = document.getElementById('city-spinner');
  spinner.classList.add('active');

  try {
    const url = `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(query)}&format=json&limit=6&addressdetails=1`;
    const res  = await fetch(url, {
      headers: { 'Accept-Language': 'en', 'User-Agent': 'RideSyncApp/1.0' }
    });
    const data = await res.json();
    renderSuggestions(data);
  } catch (err) {
    renderSuggestions([]);
  } finally {
    spinner.classList.remove('active');
  }
}

function renderSuggestions(results) {
  const list = document.getElementById('sugg-list');
  const sugg = document.getElementById('city-suggestions');

  list.innerHTML = '';

  if (!results.length) {
    list.innerHTML = '<div class="sugg-empty">No locations found</div>';
    sugg.classList.add('open');
    return;
  }

list.innerHTML = '';

  if (!results.length) {
    list.innerHTML = '<div class="sugg-empty">No locations found</div>';
    sugg.classList.add('open');
    return;
  }

  results.forEach(r => {
    const addr = r.address || {};

    // city label — most specific non-empty part
    const cityLabel =
      addr.city || addr.town || addr.village ||
      addr.county || addr.state_district || r.display_name.split(',')[0];

    // breadcrumb — state + country
    const parts = [];
    if (addr.state)   parts.push(addr.state);
    if (addr.country) parts.push(addr.country);
    const breadcrumb = parts.join(', ');

    // rounded coords
    const latR = parseFloat(r.lat).toFixed(4);
    const lonR = parseFloat(r.lon).toFixed(4);

// rounded coords
    const latR = parseFloat(r.lat).toFixed(4);
    const lonR = parseFloat(r.lon).toFixed(4);

    const item = document.createElement('div');
    item.className = 'sugg-item';
    item.innerHTML = `
      <span class="sugg-pin">📍</span>
      <div class="sugg-text">
        <div class="sugg-city">${cityLabel}</div>
        ${breadcrumb ? `<div class="sugg-breadcrumb">${breadcrumb}</div>` : ''}
      </div>
      <div class="sugg-coords">${latR}, ${lonR}</div>
    `;

    item.addEventListener('click', () => pickCity(r, cityLabel, breadcrumb));
    list.appendChild(item);
  });

  sugg.classList.add('open');
}

function pickCity(result, cityLabel, breadcrumb) {
  cityChosen = true;

  const display_name = result.display_name;
  const lat          = result.lat;
  const lng          = result.lon;   // Nominatim uses .lon

const display_name = result.display_name;
  const lat          = result.lat;
  const lng          = result.lon;   // Nominatim uses .lon

  // fill hidden fields
  document.getElementById('r-display-name').value = display_name;
  document.getElementById('r-lat').value           = lat;
  document.getElementById('r-lng').value           = lng;

  // set visible input to city label + breadcrumb
  const shortLabel = breadcrumb ? `${cityLabel}, ${breadcrumb}` : cityLabel;
  document.getElementById('r-city-input').value = shortLabel;

  // show pill
  document.getElementById('pill-name').textContent   = shortLabel;
  document.getElementById('pill-coords').textContent =
    `${parseFloat(lat).toFixed(5)}, ${parseFloat(lng).toFixed(5)}`;
  document.getElementById('city-pill').classList.add('show');

  closeSuggestions();
}

closeSuggestions();
}

function clearCity() {
  cityChosen = false;
  document.getElementById('r-city-input').value = '';
  clearCityHidden();
  document.getElementById('city-pill').classList.remove('show');
  document.getElementById('r-city-input').focus();
}

function clearCityHidden() {
  document.getElementById('r-display-name').value = '';
  document.getElementById('r-lat').value           = '';
  document.getElementById('r-lng').value           = '';
}

function closeSuggestions() {
  document.getElementById('city-suggestions').classList.remove('open');
}

/* ── SUBMIT ────────────────────────────────── */
function submitForm() {
  const err = document.getElementById('p3-err');
  const fd  = new FormData();

  fd.append('username', state.username);
  fd.append('email',    state.email);
  fd.append('password', state.password);
  if (state.pfp) fd.append('pfp', state.pfp);
  fd.append('role', state.role);

fd.append('username', state.username);
  fd.append('email',    state.email);
  fd.append('password', state.password);
  if (state.pfp) fd.append('pfp', state.pfp);
  fd.append('role', state.role);

  if (state.role === 'rider') {
    const name         = document.getElementById('r-name').value.trim();
    const age          = document.getElementById('r-age').value.trim();
    const display_name = document.getElementById('r-display-name').value;
    const lat          = document.getElementById('r-lat').value;
    const lng          = document.getElementById('r-lng').value;
    const bio          = document.getElementById('r-bio').value.trim();

    if (!name || !age) {
      err.textContent = 'Please fill in your name and age.';
      err.classList.add('show'); return;
    }

    if (!display_name || !lat || !lng) {
      err.textContent = 'Please select a city from the suggestions.';
      err.classList.add('show'); return;
    }

if (!display_name || !lat || !lng) {
      err.textContent = 'Please select a city from the suggestions.';
      err.classList.add('show'); return;
    }

    const parsedLat = parseFloat(lat);
    const parsedLng = parseFloat(lng);
    if (isNaN(parsedLat) || isNaN(parsedLng)) {
      err.textContent = 'Invalid city location. Please search again.';
      err.classList.add('show'); return;
    }

    fd.append('name',         name);
    fd.append('age',          age);
    fd.append('display_name', display_name);
    fd.append('lat',          parsedLat);
    fd.append('lng',          parsedLng);
    fd.append('bio',          bio);
    msState.bike.forEach(v  => fd.append('bikes', v));
    msState.style.forEach(v => fd.append('ridingStyle', v));

} else if (state.role === 'organizer') {
    const name  = document.getElementById('o-name').value.trim();
    const desc  = document.getElementById('o-description').value.trim();
    const gstin = document.getElementById('o-gstin').value.trim();
    if (!name || !desc || !gstin) { err.classList.add('show'); return; }
    fd.append('name',        name);
    fd.append('description', desc);
    fd.append('sociallinks', document.getElementById('o-social').value.trim());
    fd.append('website',     document.getElementById('o-website').value.trim());
    fd.append('gstin',       gstin);

} else if (state.role === 'sponsor') {
    const brand  = document.getElementById('s-brandname').value.trim();
    const desc   = document.getElementById('s-description').value.trim();
    const web    = document.getElementById('s-website').value.trim();
    const banner = document.getElementById('s-banner').files[0];
    if (!brand || !desc || !web) { err.classList.add('show'); return; }
    fd.append('brandname',   brand);
    fd.append('description', desc);
    fd.append('website',     web);
    if (banner) fd.append('banner', banner);
  }

  err.classList.remove('show');

  const submitBtn = document.querySelector('#p3 .btn-primary');
  submitBtn.disabled    = true;
  submitBtn.textContent = 'Submitting...';

  fetch('https://ride-sync-backend-v1.onrender.com/auth/signup', {
    method: 'POST',
    body: fd
  })
  .then(res => res.json())
  .then(data => {

localStorage.setItem('username', data.data.username);
    localStorage.setItem('pfp',      data.data.pfp || '');
    localStorage.setItem('email',    data.data.email || '');
    localStorage.setItem('role',     data.data.role);
    const role = data?.data?.role;
    if (role === 'rider')          window.location.href = 'new_rider_dashboard.html';
    else if (role === 'organizer') window.location.href = 'new_organizer_dashboard.html';
    else {
      err.textContent = data?.message || 'Signup failed. Please try again.';
      err.classList.add('show');
      submitBtn.disabled    = false;
      submitBtn.textContent = 'Join the Brotherhood →';
    }
  })
  .catch(() => {
    err.textContent = 'Could not reach the server. Is it running on port 3000?';
    err.classList.add('show');
    submitBtn.disabled    = false;
    submitBtn.textContent = 'Join the Brotherhood →';
  });
}
</script>
