.skeleton-meta-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem;
  margin-bottom: 1.6rem;
}
.skeleton-meta {
  height: 90px;
  background: var(--card-bg);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  position: relative; overflow: hidden;
}
.skeleton-meta::after {
  content:''; position:absolute; inset:0;
  background: linear-gradient(90deg, transparent 0%, rgba(255,255,255,.05) 50%, transparent 100%);
  animation: shimmer-pass 1.4s linear infinite;
}

@keyframes shimmer       { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
@keyframes shimmer-pass  { from { transform: translateX(-100%); } to { transform: translateX(100%); } }
@keyframes fade-in       { from { opacity:0; transform:translateY(12px); } to { opacity:1; transform:translateY(0); } }

.error-state {
  text-align: center;
  padding: 4rem 2rem;
  background: var(--card-bg);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
}
.error-icon { font-size: 2.6rem; opacity: .25; display:block; margin-bottom: 1rem; }
.error-title {
  font-family:'Montserrat',sans-serif;
  font-size: 1.4rem; font-weight: 800;
  letter-spacing: -.01em;
  color: var(--text); margin-bottom: .4rem;
  text-transform: uppercase;
}
.error-desc {
  font-family:'Barlow',sans-serif;
  font-size:.92rem; color: var(--text-dim);
  max-width: 380px; margin: 0 auto 1.4rem;
  line-height: 1.6;
}

/* ══════════════════════════════════════
   TOAST
══════════════════════════════════════ */
#toast {
  position: fixed; bottom: 28px; left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--card-bg);
  border: 1.5px solid var(--red);
  color: var(--text);
  padding: .8rem 1.4rem;
  border-radius: var(--radius-sm);
