async function get_rides(user_cords) {
    try {
        await connect_to_db();

        const res = await Ride.aggregate([
            { $geoNear: {
                near: {
                    type: 'Point', coordinates: [ user_cords.lng, user_cords.lat ]
                },
                query: {
                    status: 'Upcoming'
                },
                distanceField: "dist.calculated",
                spherical: true
            } },
            { $limit: 20 },
            { $project : { _id: 1, title: 1, description: 1, banner: 1, difficulty: 1, type: 1} }
        ]);

if(res.length === 0) {
            return {
                success: false,
                message: "No Rides available"
            };
        }
        console.log(res);
        return {
            success: true,
            data: res
        };
    }
    catch(err) {
        throw err;
    }
}

async function get_rides_type_based(type, user_cords) {
    try{
        const res = await Ride.aggregate([
            { $geoNear: {
                near: {
                    type: 'Point', coordinates: [ user_cords.lng, user_cords.lat ]
                },
                query: {
                    type: type, status: 'Upcoming'
                },
                distanceField: "dist.calculated",
                spherical: true
            } },
            { $limit: 20 },
            { $project : { _id: 1, title: 1, description: 1, banner: 1, difficulty: 1, type: 1} },
            { $sort: { startDate: 1 } }
        ]);

if(res.length == 0) {
            return {
                success: false,
                message: 'No rides available'
            };
        }

        return {
            success: true,
            data: res
        };
    }
    catch(err) {
        throw err;
    }
}

